input.newString:
const handleHomeVenueSelect = async () => {
  if (!selectedHomeSize) return;

  const venueData: VenueData = {
    name: 'Home Venue',
    address: `Your Home - ${selectedHomeSize} party`,
    rating: 5,
    distance: '0 miles',
    type: 'home',
    partySize: selectedHomeSize,
    addOns: selectedHomeAddOns
  };

  setSelectedVenue(venueData);
  console.log('Home venue selected:', venueData);

  // Save home venue selection to database
  if (currentPartyId && user?.id) {
    try {
      const response = await fetch('/api/party-venue', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          partyId: currentPartyId,
          userId: user.id,
          venue: venueData,
          isCustom: true
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to save home venue selection');
      }

      const result = await response.json();
      console.log('Home venue saved to database:', result);
    } catch (error) {
      console.error('Error saving home venue:', error);
    }
  }

  // Update local party data
  if (partyData) {
    const updatedPartyData: PartyData = {
      ...partyData,
      venue: venueData
    };

    setPartyData(updatedPartyData);
    console.log('Home venue automatically added to party');
  }
};

